<section id="receipt-view" hidden><div class="empty" id="empty"><h3>No receipt yet</h3><p>When you save the quantities received, the delivery record will appear here.</p><button class="action quiet" data-isocan-recipe="Action" id="start-receiving">Receive this shipment</button></div><article class="receipt" id="saved" hidden><span class="stamp">RECEIPT SAVED</span><h3 id="saved-title" tabindex="-1">Delivery recorded</h3><ul id="saved-lines"></ul><p class="receipt-note" id="saved-note"></p><footer><time id="saved-time"></time><button class="action quiet" data-isocan-recipe="Action" id="correct">Correct receipt</button></footer></article></section>
