try{const saved=JSON.parse(storage.getItem(key)||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))for(const order of orders){const value=saved[order.id];if(value&&Array.isArray(value.quantities)&&value.quantities.length===order.items.length&&value.quantities.every(n=>Number.isSafeInteger(n)&&n>=0)&&typeof value.note==='string'&&typeof value.at==='string')receipts[order.id]=value;}}catch{$('demo-status').textContent='Earlier local receipts could not be read. New input is still available.'}
