function remember(){drafts[selected.id]={quantities:selected.items.map((_,i)=>$('qty-'+i).value),note:$('note').value};}
function render(){const prior=receipts[selected.id],draft=drafts[selected.id];$('order-id').textContent=selected.id+' / INBOUND';$('supplier').textContent=selected.supplier;$('description').textContent=selected.description;$('reference').textContent=selected.id;$('delivery').textContent=selected.delivery;$('mobile-delivery').textContent=selected.id+' · '+selected.delivery;$('shipment-picker').value=selected.id;$('state-tag').textContent=prior?'Receipt saved':'Awaiting receipt';$('receipt-count').textContent=prior?'1':'0';$('form-title').textContent=editing?'Correct the received quantities':'What arrived?';$('save').textContent=editing?'Save correction':'Save receipt';$('error').hidden=true;$('save-status').textContent='';$('lines').replaceChildren();selected.items.forEach((item,i)=>{const row=document.createElement('div');row.className='line';const label=document.createElement('label');label.htmlFor='qty-'+i;label.textContent=item.name;const sku=document.createElement('small');sku.textContent=item.sku;label.append(sku);const expected=document.createElement('span');expected.className='expected';expected.textContent=item.ordered;const input=document.createElement('input');input.id='qty-'+i;input.type='number';input.min='0';input.max='100000';input.step='1';input.inputMode='numeric';input.value=draft?.quantities[i]??(editing?String(prior?.quantities[i]??0):'0');input.addEventListener('input',remember);row.append(label,expected,input);$('lines').append(row);});$('note').value=draft?.note??(editing?prior?.note??'':'');document.querySelectorAll('.shipment').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.id===selected.id)));$('empty').hidden=!!prior;$('saved').hidden=!prior;if(prior){$('saved-lines').replaceChildren();selected.items.forEach((item,i)=>{const li=document.createElement('li'),name=document.createElement('span'),quantity=document.createElement('strong');name.textContent=item.name;quantity.textContent=prior.quantities[i]+' units';li.append(name,quantity);$('saved-lines').append(li);});$('saved-note').textContent=prior.note||'No delivery note.';$('saved-time').textContent='Saved '+new Date(prior.at).toLocaleString();}}
for(const order of orders){const option=document.createElement('option');option.value=order.id;option.textContent=order.id+' · '+order.supplier;$('shipment-picker').append(option);const button=document.createElement('button');button.className='shipment';button.dataset.id=order.id;const id=document.createElement('em'),name=document.createElement('strong'),detail=document.createElement('span');id.textContent=order.id;name.textContent=order.supplier;detail.textContent=order.items.length+' lines · '+order.delivery.split(' · ')[0].toLowerCase();button.append(id,name,detail);button.addEventListener('click',()=>{if(busy)return;remember();selected=order;editing=!!receipts[order.id];render();view(false)});$('shipments').append(button);}
$('shipment-picker').onchange=()=>{remember();selected=orders.find(order=>order.id===$('shipment-picker').value);editing=!!receipts[selected.id];render();view(false)};$('note').addEventListener('input',remember);$('receive-tab').onclick=()=>view(false);$('receipt-tab').onclick=()=>view(true);$('start-receiving').onclick=()=>{view(false);$('qty-0').focus()};$('correct').onclick=()=>{editing=true;delete drafts[selected.id];render();view(false);$('qty-0').focus()};
$('receive-form').addEventListener('submit',async event=>{event.preventDefault();if(busy)return;remember();const values=selected.items.map((_,i)=>$('qty-'+i).value),quantities=values.map(Number);const bad=values.findIndex((value,i)=>value.trim()===''||!Number.isSafeInteger(quantities[i])||quantities[i]<0||quantities[i]>100000);if(bad>=0||!quantities.some(n=>n>0)){$('error').textContent=bad>=0?'Enter a whole number from 0 to 100,000 for each item.':'Enter at least one received quantity before saving.';$('error').hidden=false;$('qty-'+Math.max(bad,0)).focus();return;}const note=$('note').value.trim();$('error').hidden=true;busy=true;document.querySelectorAll('#receive-form input,#receive-form textarea,.shipment,#shipment-picker,.tab,#correct,#start-receiving,#fail-next,#clear-receipt').forEach(control=>control.disabled=true);$('save').disabled=true;$('save').textContent='Saving…';$('save-status').textContent='Saving this receipt…';try{await new Promise(resolve=>setTimeout(resolve,350));if(failNext){failNext=false;throw Error('The receipt could not be saved. Your quantities and note are still here. Try again.');}const receipt={quantities,note,at:new Date().toISOString()};const updated={...receipts,[selected.id]:receipt};storage.setItem(key,JSON.stringify(updated));receipts=updated;delete drafts[selected.id];editing=true;render();view(true);$('saved-title').focus();}catch(error){$('error').textContent=error.message||'Browser storage is unavailable. Keep this page open and try saving again.';$('error').hidden=false;$('save-status').textContent='Not saved.';}finally{busy=false;document.querySelectorAll('#receive-form input,#receive-form textarea,.shipment,#shipment-picker,.tab,#correct,#start-receiving,#fail-next,#clear-receipt').forEach(control=>control.disabled=false);$('save').disabled=false;$('save').textContent=editing?'Save correction':'Save receipt';}});
